#include <bits/stdc++.h>
using namespace std;

void apply(vector<int>& p, int x, int y) {
    int n = p.size();
    // [0..x-1] [x..n-1-y] [n-y..n-1] -> [n-y..n-1] [x..n-1-y] [0..x-1]
    vector<int> np;
    for (int i = n-y; i < n; i++) np.push_back(p[i]);
    for (int i = x; i < n-y; i++) np.push_back(p[i]);
    for (int i = 0; i < x; i++) np.push_back(p[i]);
    p = np;
}

int main(){
    int n;
    scanf("%d",&n);
    vector<int> p(n);
    for(int i=0;i<n;i++) scanf("%d",&p[i]);

    vector<pair<int,int>> ops;

    auto doOp = [&](int x, int y) {
        assert(x > 0 && y > 0 && x + y < n);
        ops.push_back({x, y});
        apply(p, x, y);
    };

    for(int k = 0; k < n-2; k++) {
        // Place element k+1 at position k
        int pos = -1;
        for(int i = k; i < n; i++) if(p[i] == k+1) { pos = i; break; }
        if(pos == k) continue;

        // Step 1: Move element to last position (n-1)
        if(pos != n-1) {
            // We want to move p[pos] to position n-1
            // Use x = pos+1, y = n-1-pos, but need x+y < n
            // x+y = pos+1 + n-1-pos = n, so we need middle non-empty
            // Instead: x = pos, y = n-1-pos if pos > 0
            if(pos > 0 && pos < n-1) {
                // x=pos, y=n-1-pos: x+y = n-1 < n. Good.
                // After: [n-1-pos elems from end] [middle: pos..pos] [prefix: 0..pos-1]
                // Wait, suffix = p[pos+1..n-1] (length n-1-pos), middle = p[pos..pos], prefix = p[0..pos-1]
                // Result: suffix + middle + prefix. Element at pos is now at position (n-1-pos).
                doOp(pos, n-1-pos);
                pos = n-1-pos; // element moved here
            }
            // If still not at n-1, try again
            if(pos != n-1 && pos > 0) {
                // x=pos, y=n-1-pos
                if(pos + (n-1-pos) < n) {
                    doOp(pos, n-1-pos);
                    pos = n-1-pos;
                }
            }
            if(pos == 0 && n > 2) {
                // Move from 0 to end: x=1, y=n-2 => x+y=n-1<n
                doOp(1, n-2);
                // element was at 0 (prefix), goes to end (last of new array)
                pos = n-1;
            }
        }

        // Step 2: Move element from position n-1 to position k
        if(pos == n-1 && k < n-1) {
            // x=k+1, y=1: suffix=[p[n-1]], middle=[p[k+1..n-2]], prefix=[p[0..k]]
            // Result: [p[n-1]] + [p[k+1..n-2]] + [p[0..k]]
            // Element goes to position 0, not k!
            // Instead: x=k, y=1 if k>0: Result: [p[n-1]] + [p[k..n-2]] + [p[0..k-1]]
            // Element at position 0, need it at k
            // Actually let's think differently:
            // We want element at n-1 to end up at position k
            // After op(x,y): suffix(y) + middle + prefix(x)
            // Element is in suffix (last y=1 element), goes to position 0
            // To get it to position k, we need k elements before it
            // Those k elements should come from the suffix. So y = k+1? 
            // But element is at n-1, the last position of suffix of length y=k+1 would be p[n-k-1..n-1]
            // Element at n-1 goes to position k (last of suffix block). 
            // Need x > 0, x + k+1 < n => x < n-k-1. Use x=1 if k+1 < n-1.
            if(k == 0) {
                doOp(1, 1);
                // suffix=[p[n-1]], middle=[p[1..n-2]], prefix=[p[0]]
                // element goes to pos 0. Good!
            } else {
                int y = k + 1;
                int x = 1;
                if(x + y < n) {
                    doOp(x, y);
                    // element was at n-1, which is last of suffix, goes to position y-1 = k
                } else if(k+2 < n) {
                    doOp(1, k+1 < n-1 ? k+1 : k);
                }
            }
        }
    }

    printf("%d\n",(int)ops.size());
    for(auto&[x,y]:ops) printf("%d %d\n",x,y);
}
